def _huff_avg(P):
    q = sorted(P)
    total = 0.0
    while len(q) > 1:
        a, b = q[0], q[1]
        q = sorted(q[2:] + [a + b])
        total += a + b
    return total

def _prefix_ok(C):
    return all(not (i != j and b.startswith(a)) for i, a in enumerate(C) for j, b in enumerate(C))

def _avg_ok(P, C):
    return abs(sum(p * len(w) for p, w in zip(P, C)) - _huff_avg(P)) < 1e-9

def _kraft_ok(C):
    return sum(2 ** -len(w) for w in C) <= 1 + 1e-12

def _bits_ok(C):
    return len(C) > 0 and all(len(w) > 0 and set(w) <= {"0", "1"} for w in C)
